INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "租庸使因仓储不足减军粮，宰相百官请求用内库财救军。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p037·原文件第74行", "note": "原文：租庸使以仓储不足，颇朘刻军粮，军士流言益甚。宰相惧，帅百官上表言：“今租庸已竭，内库有馀，诸军室家不能相保，傥不赈救，惧有离心。俟过凶年，其财复集。”；核对说明：租庸使本句未具姓名不擅置孔谦为实际裁令者；内库有余是上表主张，不当已实地核查库存。离心为所忧未来。", "status": "draft", "id": "c4e103dc-bf2b-5281-8b78-f2a3961b27b4", "subject_id": "b46589ab-a7c5-5603-9534-116a46c1180f", "source_id": "bafce597-87cc-5127-84a7-411b0ca0e080"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年三月军粮危机时", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p037·原文件第74行", "note": "原文：租庸使以仓储不足，颇朘刻军粮，军士流言益甚。宰相惧，帅百官上表言：“今租庸已竭，内库有馀，诸军室家不能相保，傥不赈救，惧有离心。俟过凶年，其财复集。”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "0d1b0f10-9b96-53a6-9cfa-04720ea2ae38", "subject_id": "b46589ab-a7c5-5603-9534-116a46c1180f", "source_id": "bafce597-87cc-5127-84a7-411b0ca0e080"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧本纪记壬戌豆卢革率百官请出内府金帛，不报。", "citation": "《旧五代史》卷三十四，段落 jiu-wudaishi-205deb4a7860-p001066；EPUB电子本，纸本及异文待核", "note": "原文：壬戌，宰臣豆盧革率百官上表，以魏博軍變，請出內府金帛優給將士。不報。；核对说明：旧补领表者与日期，不报与主皇帝欲从后受阻叙法有别，不把已经上表等同成功筹款。", "status": "draft", "id": "e9535132-17b7-5102-86d9-192b6f97da34", "subject_id": "b46589ab-a7c5-5603-9534-116a46c1180f", "source_id": "f8898647-30b0-5b83-adf5-fd792e11cf70"}, {"subject_table": "event", "field_path": "description", "claim_text": "李存勖欲采上表，刘后以天命说回应。", "citation": "卷274·同光四年（926）·zztj-v274-y0926-p037·原文件第74行", "note": "原文：上即欲从之，刘后曰：“吾夫妇君临万国，虽藉武功，亦由天命。命既在天，人如我何！”；核对说明：天命与人如我何为皇后自述，不当超自然事实；欲从是态度，非已执行。", "status": "draft", "id": "2ca4e172-8c99-512d-8610-1183baffe1f9", "subject_id": "ba622056-a4e4-5d0d-8eeb-09ea4641bf93", "source_id": "bafce597-87cc-5127-84a7-411b0ca0e080"}, {"subject_table": "event", "field_path": "time_original", "claim_t